/* ============================================================
   Yayika — Share & Earn Schema
   Trackable achievement cards for social sharing
   ============================================================ */

-- ============================================================
-- TABLES
-- ============================================================

-- Share cards generated by users
CREATE TABLE IF NOT EXISTS yayika_share_cards (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
  card_type TEXT NOT NULL, -- 'achievement', 'badge', 'streak', 'milestone', 'referral', 'custom'
  card_title JSONB NOT NULL, -- {"es":"Logro desbloqueado","en":"Achievement Unlocked",...}
  card_subtitle JSONB NOT NULL, -- {"es":"7 días de racha","en":"7-day streak",...}
  card_icon TEXT DEFAULT '🌟', -- Emoji or icon identifier
  card_color TEXT DEFAULT '#7B5EA7', -- Accent color
  card_data JSONB DEFAULT '{}', -- Extra data (badge_key, streak_count, etc.)
  ref_code TEXT, -- Embedded referral code
  share_url TEXT, -- Generated share URL
  share_count INT DEFAULT 0,
  view_count INT DEFAULT 0,
  click_count INT DEFAULT 0,
  conversion_count INT DEFAULT 0,
  platform TEXT, -- 'instagram', 'tiktok', 'whatsapp', 'twitter', 'copy', null
  is_public BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Track individual share events
CREATE TABLE IF NOT EXISTS yayika_share_events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  card_id UUID REFERENCES yayika_share_cards(id) ON DELETE CASCADE NOT NULL,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
  event_type TEXT NOT NULL, -- 'share', 'view', 'click', 'conversion'
  platform TEXT, -- 'instagram', 'tiktok', 'whatsapp', etc.
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Predefined card templates
CREATE TABLE IF NOT EXISTS yayika_share_templates (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  template_key TEXT UNIQUE NOT NULL,
  card_type TEXT NOT NULL,
  title JSONB NOT NULL,
  subtitle_template TEXT, -- Template with placeholders like {count}, {name}
  icon TEXT,
  color TEXT,
  gradient TEXT,
  is_active BOOLEAN DEFAULT true,
  sort_order INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- User share stats (aggregated)
CREATE TABLE IF NOT EXISTS yayika_share_stats (
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE PRIMARY KEY,
  total_shares INT DEFAULT 0,
  total_views INT DEFAULT 0,
  total_clicks INT DEFAULT 0,
  total_conversions INT DEFAULT 0,
  referral_signups INT DEFAULT 0,
  last_share_at TIMESTAMPTZ,
  share_streak INT DEFAULT 0,
  best_share_streak INT DEFAULT 0,
  xp_earned INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ============================================================
-- INDEXES
-- ============================================================

CREATE INDEX IF NOT EXISTS idx_sc_user ON yayika_share_cards(user_id);
CREATE INDEX IF NOT EXISTS idx_sc_type ON yayika_share_cards(card_type);
CREATE INDEX IF NOT EXISTS idx_sc_created ON yayika_share_cards(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_se_card ON yayika_share_events(card_id);
CREATE INDEX IF NOT EXISTS idx_se_user ON yayika_share_events(user_id);

