-- ============================================================
-- FUNCTIONS
-- ============================================================

-- Create a share card
CREATE OR REPLACE FUNCTION yayika_create_share_card(
  p_user_id UUID,
  p_card_type TEXT,
  p_card_title JSONB,
  p_card_subtitle JSONB,
  p_card_icon TEXT DEFAULT '🌟',
  p_card_color TEXT DEFAULT '#7B5EA7',
  p_card_data JSONB DEFAULT '{}',
  p_ref_code TEXT DEFAULT NULL
) RETURNS UUID AS $$
DECLARE
  v_card_id UUID;
  v_share_url TEXT;
BEGIN
  -- Generate share URL with referral code
  v_share_url := 'https://yayika.com/share/' || p_ref_code || '?card=' || p_card_type;

  INSERT INTO yayika_share_cards (
    user_id, card_type, card_title, card_subtitle, card_icon, card_color,
    card_data, ref_code, share_url
  ) VALUES (
    p_user_id, p_card_type, p_card_title, p_card_subtitle, p_card_icon, p_card_color,
    p_card_data, p_ref_code, v_share_url
  ) RETURNING id INTO v_card_id;

  -- Update share stats
  INSERT INTO yayika_share_stats (user_id, total_shares, last_share_at, updated_at)
  VALUES (p_user_id, 1, NOW(), NOW())
  ON CONFLICT (user_id) DO UPDATE SET
    total_shares = yayika_share_stats.total_shares + 1,
    last_share_at = NOW(),
    updated_at = NOW();

  -- Record growth activity
  PERFORM yayika_record_growth_activity(p_user_id, 'share_click', jsonb_build_object('card_type', p_card_type, 'card_id', v_card_id));

  RETURN v_card_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Record a share event (platform share)
CREATE OR REPLACE FUNCTION yayika_record_share_event(
  p_card_id UUID,
  p_user_id UUID,
  p_event_type TEXT,
  p_platform TEXT DEFAULT NULL
) RETURNS VOID AS $$
BEGIN
  INSERT INTO yayika_share_events (card_id, user_id, event_type, platform)
  VALUES (p_card_id, p_user_id, p_event_type, p_platform);

  -- Update card counts
  IF p_event_type = 'share' THEN
    UPDATE yayika_share_cards SET share_count = share_count + 1, platform = p_platform WHERE id = p_card_id;
  ELSIF p_event_type = 'view' THEN
    UPDATE yayika_share_cards SET view_count = view_count + 1 WHERE id = p_card_id;
  ELSIF p_event_type = 'click' THEN
    UPDATE yayika_share_cards SET click_count = click_count + 1 WHERE id = p_card_id;
  ELSIF p_event_type = 'conversion' THEN
    UPDATE yayika_share_cards SET conversion_count = conversion_count + 1 WHERE id = p_card_id;
  END IF;

  -- Update user stats
  UPDATE yayika_share_stats SET
    total_views = total_views + CASE WHEN p_event_type = 'view' THEN 1 ELSE 0 END,
    total_clicks = total_clicks + CASE WHEN p_event_type = 'click' THEN 1 ELSE 0 END,
    total_conversions = total_conversions + CASE WHEN p_event_type = 'conversion' THEN 1 ELSE 0 END,
    referral_signups = referral_signups + CASE WHEN p_event_type = 'conversion' THEN 1 ELSE 0 END,
    updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Award XP for sharing
  IF p_event_type = 'share' THEN
    UPDATE yayika_share_stats SET xp_earned = xp_earned + 10 WHERE user_id = p_user_id;
    PERFORM yayika_record_growth_activity(p_user_id, 'share_click', jsonb_build_object('platform', p_platform));
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Get user share stats
CREATE OR REPLACE FUNCTION yayika_get_share_stats(p_user_id UUID)
RETURNS TABLE(
  total_shares INT,
  total_views INT,
  total_clicks INT,
  total_conversions INT,
  referral_signups INT,
  share_streak INT,
  best_share_streak INT,
  xp_earned INT,
  recent_cards JSONB
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(ss.total_shares, 0),
    COALESCE(ss.total_views, 0),
    COALESCE(ss.total_clicks, 0),
    COALESCE(ss.total_conversions, 0),
    COALESCE(ss.referral_signups, 0),
    COALESCE(ss.share_streak, 0),
    COALESCE(ss.best_share_streak, 0),
    COALESCE(ss.xp_earned, 0),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', sc.id,
        'card_type', sc.card_type,
        'card_title', sc.card_title,
        'card_subtitle', sc.card_subtitle,
        'card_icon', sc.card_icon,
        'card_color', sc.card_color,
        'share_count', sc.share_count,
        'view_count', sc.view_count,
        'created_at', sc.created_at
      ) ORDER BY sc.created_at DESC)
      FROM yayika_share_cards sc WHERE sc.user_id = p_user_id LIMIT 10
    ), '[]'::jsonb)
  FROM yayika_share_stats ss
  WHERE ss.user_id = p_user_id;

  -- If no stats row, return empty
  IF NOT FOUND THEN
    total_shares := 0; total_views := 0; total_clicks := 0; total_conversions := 0;
    referral_signups := 0; share_streak := 0; best_share_streak := 0; xp_earned := 0;
    recent_cards := '[]'::jsonb;
    RETURN NEXT;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Get shareable card data for templates
CREATE OR REPLACE FUNCTION yayika_get_share_templates()
RETURNS TABLE(
  template_key TEXT,
  card_type TEXT,
  title JSONB,
  subtitle_template TEXT,
  icon TEXT,
  color TEXT,
  gradient TEXT
) AS $$
BEGIN
  RETURN QUERY
  SELECT st.template_key, st.card_type, st.title, st.subtitle_template, st.icon, st.color, st.gradient
  FROM yayika_share_templates st WHERE st.is_active = true ORDER BY st.sort_order;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================
-- ROW LEVEL SECURITY
-- ============================================================

ALTER TABLE yayika_share_cards ENABLE ROW LEVEL SECURITY;
ALTER TABLE yayika_share_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE yayika_share_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE yayika_share_stats ENABLE ROW LEVEL SECURITY;

-- Public read: templates
CREATE POLICY "pub_read_templates" ON yayika_share_templates FOR SELECT USING (is_active = true);

-- Public read: public cards (for share links)
CREATE POLICY "pub_read_public_cards" ON yayika_share_cards FOR SELECT USING (is_public = true);

-- User: own cards
CREATE POLICY "user_read_own_cards" ON yayika_share_cards FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "user_insert_own_cards" ON yayika_share_cards FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "user_update_own_cards" ON yayika_share_cards FOR UPDATE USING (auth.uid() = user_id);

-- User: own events
CREATE POLICY "user_read_own_events" ON yayika_share_events FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "user_insert_own_events" ON yayika_share_events FOR INSERT WITH CHECK (auth.uid() = user_id);

-- User: own stats
CREATE POLICY "user_read_own_stats" ON yayika_share_stats FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "user_insert_own_stats" ON yayika_share_stats FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "user_update_own_stats" ON yayika_share_stats FOR UPDATE USING (auth.uid() = user_id);

-- Service role: full access
CREATE POLICY "svc_all_cards" ON yayika_share_cards FOR ALL USING (auth.role() = 'service_role');
CREATE POLICY "svc_all_events" ON yayika_share_events FOR ALL USING (auth.role() = 'service_role');
CREATE POLICY "svc_all_templates" ON yayika_share_templates FOR ALL USING (auth.role() = 'service_role');
CREATE POLICY "svc_all_stats" ON yayika_share_stats FOR ALL USING (auth.role() = 'service_role');
